def _may_beat(rival, c):
    """An open rival can still undercut an agreement: it is cheaper already, or still moving."""
    return rival.get("c") is None or c is None or rival["c"] < c or (rival.get("move_pct") or 0) > 0


def route(case, ledgers, ready, c_alt, knobs, last_round):
    """Close now (accept/walk) or negotiate with the ready suppliers; `final_push` marks trade-only pushes."""
    live = [s for s, led in ledgers.items() if not led.get("ended")]
    # Only a ready supplier can receive our closing action. If a busy one has a better offer, the
    # engine sees our close while that request is in flight and itself accepts the cheapest acceptable
    # offer once the reply has settled (engine.py: close with pending -> close_action).
    best = best_acceptable({s: ledgers[s] for s in ready if s in live})
    fallback_exists = c_alt is not None

    def accept_best(reason):
        if best:
            sid = best[1]
            return _close("accept", sid, ledgers[sid]["offer_id"], reason)
        return _close("walk", ready[0], reason=reason + " (nothing acceptable)")

    if last_round:
        return accept_best("wave time")
    for sid in ready:
        if ledgers[sid]["moves_left"] <= 0:
            return accept_best("no moves left")
    pushes, holds = {}, {}

    def open_rivals(sid):
        return [
            s
            for s in live
            if s != sid and ledgers[s]["status"] not in ("final_offer", "agreed") and ledgers[s]["moves_left"] >= 1
        ]

    # The cheapest acceptable final offer is our fallback when there is no alternative: never push it.
    finals = sorted(
        (ledgers[s]["c"], s)
        for s in live
        if ledgers[s]["status"] == "final_offer" and ledgers[s].get("acceptable") and ledgers[s]["c"] is not None
    )
    protected = finals[0][1] if finals else None
    for sid in sorted(ready, key=lambda s: s == protected):  # the protected fallback is decided last
        led = ledgers[sid]
        if led["status"] == "agreed" and led.get("acceptable"):
            # An agreement is our fallback while a rival can still beat it.
            if led["moves_left"] >= 2 and [s for s in open_rivals(sid) if _may_beat(ledgers[s], led["c"])]:
                holds[sid] = True
                continue
            return accept_best("agreed")
        if led["status"] != "final_offer":
            continue
        if led.get("alt_better") and led["moves_left"] >= 1:
            pushes[sid] = True  # its cheaper alternative: we send its own terms back (graph._mirror), no push
            continue
        others_open = open_rivals(sid)
        pushable = knobs.get("allow_final_push", True) and led["pushes_after_final"] == 0 and led["moves_left"] >= 2
        # push only when its walking costs us nothing: our alternative is at least as good, or a cheaper
        # final offer stays as fallback. Open rivals are no such guarantee, and no deal scores 0 when the
        # alternative is no better than the opening.
        alt_as_good = fallback_exists and led["c"] is not None and c_alt <= led["c"]
        safe = alt_as_good or (protected not in (None, sid) and not pushes)
        if pushable and safe:
            pushes[sid] = True
            continue
        if (others_open or pushes) and led["moves_left"] >= 2:
            holds[sid] = True  # its final offer stands as our fallback while the others negotiate
            continue
        if led.get("acceptable"):
            return accept_best("final offer")
        if fallback_exists and not [s for s in live if s != sid]:
            return _close("walk", sid, reason="final offer worse than our alternative")
    return {"type": "negotiate", "suppliers": list(ready), "final_push": pushes, "hold": holds}


def tone_for(tags, lessons_tone=None):
    if lessons_tone:
        return lessons_tone
    if set(tags) & WARM:
        return "warm"
    if set(tags) & FIRM:
        return "firm"
    return "neutral"


def det_choose(sid, led, menu, claims, tags, final_push, first, knobs):
    """The deterministic move: same menu and claims the model would see, a fixed schedule."""
    level = "trade" if final_push else "step"
    sheets = [m for m in menu if m["level"] == level] or [m for m in menu if m["level"] == "hold"] or menu
    sheets = sheets[:2]
    n_claims = 2 if first else 1
    chosen = [c for c in claims if not c.get("reveals")][:n_claims] or claims[:n_claims]
    ask = first or (
        not led.get("breakdown") and led.get("rounds", 0) <= 1 and bool(set(tags) & {"open_books", "weak_costing"})
    )
    tactic = "trade" if final_push else ("anchor" if first else "concede")
    return {
        "tactic": tactic,
        "sheet_ids": [m["mid"] for m in sheets],
        "claim_ids": [c["cid"] for c in chosen][:MAX_PER_MESSAGE],
        "ask_breakdown": ask,
        "tone": tone_for(tags, knobs.get("tone", {}).get(sid)),
        "questions": [],
        "prediction": {"status": "open", "price_move_pct": None, "note": "deterministic"},
        "read": "",
    }
"""Claim Cataloguer: data arguments that pass the arena's check, with the figure computed in code.

Rules follow brief/api.md "What counts": one argument per sentence, the figure in the same sentence
as its IDs, tolerance ±0.5 pp / ±0.5 %, at most 3 checked per message, each ID once per case.
Only claims that help the buyer are listed (an index only when it fell); the model chooses among them by `cid`.
"""

import re

from .offers import should_cost_row

ID_RE = re.compile(r"\b(?:po|idx|sc|ctr|doc|quote|offer|qn|fc|cost|news|rfq|sup|part):[\w.\-@#]+")
FAVOURABLE_NEWS = {"free_capacity", "short_time_work"}
MAX_PER_MESSAGE = 3
# What we paid before is no cost argument to a supplier: in every practice reply (23, seven suppliers) price
# history came back "it holds, but it does not change our calculation". It stays available, ranked last.
PRICE_HISTORY_STRENGTH = 0.15


def ids_in(text):
    return [m.rstrip(".,;)") for m in ID_RE.findall(text or "")]


PER_SUPPLIER = ("quote:", "offer:")  # a rival's quote counts once per supplier, every other ID once per case


def used_ids(threads):
    """IDs already cited, as the arena counts them: {supplier: IDs that would be a duplicate there}."""
    per_sup, case_wide = {}, set()
    for sid, events in threads.items():
        seen = per_sup.setdefault(sid, set())
        for m in events:
            if m.get("from") == "buyer":
                ids = set(m.get("refs") or []) | set(ids_in(m.get("body")))
                seen.update(i for i in ids if i.startswith(PER_SUPPLIER))
                case_wide.update(i for i in ids if not i.startswith(PER_SUPPLIER))
    return {sid: seen | case_wide for sid, seen in per_sup.items()}


